 if(url.pathname==='/source/raw'){const p=url.searchParams.get('path');return Object.hasOwn(review.files,p)?new Response(review.files[p],{headers:{'Content-Type':'text/plain; charset=utf-8','X-Content-Type-Options':'nosniff'}}):new Response('Not found',{status:404});}
 if(url.pathname!=='/source')return null;
